"""Render the interactive Fair Share world map for the IIASA dashboard.

Pass the dictionary returned by fair_share.calculate(), not the weights JSON:

    from fair_share_map import render_fair_share_map

    page = render_fair_share_map(result)  # Adjusted relative gap by default

Serve the returned document as text/html, or load it in a dashboard iframe
with scripts enabled. Render a new document when the dashboard selection changes. No notebook,
external map files, internet access, or third-party Python packages are needed.

To preview saved results locally:

    python fair_share_map.py fair_share_result.json fair_share_map.html
"""

from __future__ import annotations

import argparse
import base64
import gzip
import json
from functools import lru_cache
from html import escape
from math import isfinite
from pathlib import Path

APPROACHES = {
    "AP": "Ability to Pay",
    "HR": "Historical Responsibility",
    "EQ": "Equality (IEPC)",
}

ZERO_TOLERANCE = 1e-9  # MtCO2e
NO_DATA, AT_ALLOWANCE = "#B9C2CF", "#FFD21C"
RED_LIGHT, RED_DARK = "#F38B79", "#A3132A"
GREEN, BLUE = "#23AF63", "#143D99"


def render_fair_share_map(
    result: dict,
    *,
    variant: str = "adjusted",
    metric: str = "relative",
    max_abs: float | None = None,
) -> str:
    """Return a standalone, clickable HTML map with one panel per approach.

    Set variant to "base" or "adjusted" and metric to "relative" (%) or
    "absolute" (MtCO2e). Set max_abs to a positive limit to keep the same
    symmetric colour scale across different dashboard selections.

    The relative gap is (allowance - emissions) / abs(emissions) × 100.
    It is not the change from Base to Adjusted. Near-zero emissions have
    no relative gap. A near-zero signed gap is yellow in either view.
    """
    if variant not in {"base", "adjusted"}:
        raise ValueError('variant must be "base" or "adjusted".')
    if metric not in {"relative", "absolute"}:
        raise ValueError('metric must be "relative" or "absolute".')
    if max_abs is not None and (
        isinstance(max_abs, bool) or not isfinite(max_abs) or max_abs <= 0
    ):
        raise ValueError("max_abs must be a positive finite number.")

    rows = result.get("detail")
    if not isinstance(rows, list):
        raise ValueError("Expected the result of fair_share.calculate(), with a detail list.")
    details = {(row["participant_id"], row["approach"]): row for row in rows}
    if len(details) != len(rows):
        raise ValueError("Fair Share results contain duplicate participant–approach rows.")

    countries, definitions = _map_geometry()
    records = {
        (i, approach): _country_result(iso, name, approach, details, variant, metric)
        for i, (iso, name, _) in enumerate(countries)
        for approach in APPROACHES
    }
    magnitudes = [abs(value) for _, value, _ in records.values() if value is not None]
    limit = max_abs if max_abs is not None else (max(magnitudes, default=0.0) or 1.0)

    panels = []
    for approach, name in APPROACHES.items():
        shapes = []
        for i, (iso, country, _) in enumerate(countries):
            gap, value, info = records[i, approach]
            message = escape(info, quote=True).replace("\n", "&#10;")
            label = escape(f"{country}, {approach}. Show Fair Share result.", quote=True)
            shapes.append(
                f'<use href="#country-{i}" fill="{_colour(gap, value, limit)}" '
                f'data-iso="{escape(iso, quote=True)}" data-result="{message}" '
                f'tabindex="0" role="button" aria-label="{label}">'
                f'<title>{escape(country)} · Click for result</title></use>'
            )
        panels.append(
            f'<section data-approach="{approach}"><h2>{approach} · {name}</h2>'
            f'<svg viewBox="-2.72 -1.39 5.44 2.49" aria-label="{approach} world map">'
            f'{"".join(shapes)}</svg></section>'
        )

    unit = "%" if metric == "relative" else "MtCO₂e"
    metric_title = "Relative emissions gap (%)" if metric == "relative" else "Emissions gap (MtCO₂e)"
    title = f"{variant.title()} Fair Share allowance · {metric_title}"
    subtitle = _scope_label(result.get("metadata") or {})
    scale_number = f"{limit:,.2f}".rstrip("0").rstrip(".") if limit >= 0.01 else f"{limit:.3g}"
    scale_label = f"{scale_number} {unit}"
    return f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)}</title>
<style>{_STYLE}</style>
</head>
<body>
<svg class="definitions" width="0" height="0" aria-hidden="true"><defs>{definitions}</defs></svg>
<h1>{escape(title)}</h1>
<p class="subtitle">{escape(subtitle)}</p>
<div class="maps">{"".join(panels)}</div>
<div class="legend" aria-label="Map colour scale">
  <span><i class="swatch red"></i>Above allowance · −{scale_label} to 0</span>
  <span><i class="swatch yellow"></i>At allowance · 0</span>
  <span><i class="swatch green"></i>Below allowance · 0 to +{scale_label}</span>
  <span><i class="swatch grey"></i>No data / undefined</span>
</div>
<div id="result" role="status" aria-live="polite">
  Click a country in any panel to see its allowance, emissions and gap.
</div>
<p class="note">Shared colour scale across AP, HR and EQ. For regional participants,
each member country displays the same regional result.</p>
<p class="note">Boundaries: Natural Earth, 1:50m Admin 0 Countries, simplified.</p>
<script>{_SCRIPT}</script>
</body>
</html>
"""


def _country_result(iso, country, approach, details, variant, metric):
    participant = _MEMBER_OF.get(iso)
    row = details.get((participant, approach))
    heading = f"{country} ({iso}) · {approach} · {variant.title()}"
    if row is None:
        return None, None, f"{heading}\nNo Fair Share result for this selection."

    values = row[variant]
    emissions = _finite_or_none(row["net_afolu_mtco2e"])
    allowance = _finite_or_none(values["allowance_mtco2e"])
    gap = _finite_or_none(values["gap_mtco2e"])
    if gap is None:
        status = "Not available"
    elif abs(gap) <= ZERO_TOLERANCE:
        status = "At allowance"
    else:
        status = "Above allowance" if gap < 0 else "Below allowance"

    relative = None
    if gap is not None and emissions is not None and abs(emissions) > ZERO_TOLERANCE:
        relative = _finite_or_none(100 * (gap / abs(emissions)))
    value = relative if metric == "relative" else gap

    participant_label = f"FABLE participant: {participant}"
    if participant.startswith("R_"):
        participant_label += " · Regional totals, not a separate country result."
    info = "\n".join([
        heading,
        participant_label,
        f"Status: {status}",
        f"Cumulative net AFOLU: {_format(emissions, 'MtCO₂e')}",
        f"Fair allowance: {_format(allowance, 'MtCO₂e')}",
        f"Signed gap (allowance − emissions): {_format(gap, 'MtCO₂e')}",
        f"Relative gap: {_format(relative, '%')}",
    ])
    return gap, value, info


def _finite_or_none(value):
    return value if value is not None and isfinite(value) else None


def _format(value, unit):
    if value is None:
        return "Not available"
    rounded = round(value, 2)
    return f"{rounded or 0.0:,.2f} {unit}"


def _scope_label(metadata):
    parts = [str(metadata["pathway"])] if metadata.get("pathway") else []
    trade_adj = metadata.get("trade_adj")
    if isinstance(trade_adj, bool):
        parts.append("After trade adjustment" if trade_adj else "Before trade adjustment")
    start, end = metadata.get("period_start"), metadata.get("period_end")
    if start is not None and end is not None:
        parts.append(f"{start}–{end}")
    return " · ".join(parts)


def _colour(gap, value, limit):
    if gap is None:
        return NO_DATA
    if abs(gap) <= ZERO_TOLERANCE:
        return AT_ALLOWANCE
    if value is None:
        return NO_DATA

    fraction = min(abs(value) / limit, 1.0)
    start, end = (RED_LIGHT, RED_DARK) if gap < 0 else (GREEN, BLUE)
    start_rgb = bytes.fromhex(start[1:])
    end_rgb = bytes.fromhex(end[1:])
    rgb = bytes(round(a + (b - a) * fraction) for a, b in zip(start_rgb, end_rgb))
    return "#" + rgb.hex()


@lru_cache(maxsize=1)
def _map_geometry():
    """Decode the bundled map once and share its outlines across all panels."""
    countries = json.loads(gzip.decompress(base64.b64decode(_GEOMETRY)))
    definitions = "".join(
        f'<path id="country-{i}" d="{path}" fill-rule="evenodd"/>'
        for i, (_, _, path) in enumerate(countries)
    )
    return countries, definitions


_STYLE = """
* { box-sizing: border-box }
body { margin: 0; padding: 20px; font: 14px system-ui, sans-serif; color: #14283f; background: white }
h1 { margin: 0 0 5px; font-size: 24px }
.subtitle { margin: 0 0 18px; color: #52657c }
.definitions { position: absolute }
.maps { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px }
section { border: 1px solid #dce5ef; border-radius: 10px; padding: 10px 6px; background: #f7fafc }
h2 { margin: 0 0 9px; font-size: 13px; text-align: center }
section svg { display: block; width: 100% }
use[data-result] { stroke: #fff; stroke-width: .0045; cursor: pointer }
use[data-result]:hover, use[data-result]:focus, use.active { stroke: #14283f; stroke-width: .014 }
.legend { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px 22px; margin: 16px 0 }
.legend span { display: inline-flex; align-items: center; gap: 6px; font-size: 12px }
.swatch { width: 35px; height: 10px; border: 1px solid #8090a3; border-radius: 3px }
.red { background: linear-gradient(90deg, #a3132a, #f38b79) }
.yellow { background: #ffd21c }
.green { background: linear-gradient(90deg, #23af63, #143d99) }
.grey { background: #b9c2cf }
#result { white-space: pre-line; padding: 12px 15px; border: 1px solid #dce5ef;
          border-left: 4px solid #315a9f; border-radius: 8px; background: #f5f8fc; line-height: 1.48 }
.note { margin: 8px 0 0; font-size: 11px; color: #52657c }
@media (max-width: 650px) { .maps { grid-template-columns: 1fr } }
"""

_SCRIPT = """
const result = document.getElementById("result");
let activeCountry;

function showResult(country) {
    if (activeCountry) activeCountry.classList.remove("active");
    activeCountry = country;
    activeCountry.classList.add("active");
    result.textContent = country.dataset.result;
}

document.querySelectorAll("use[data-result]").forEach(country => {
    country.addEventListener("click", () => showResult(country));
    country.addEventListener("keydown", event => {
        if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            showResult(country);
        }
    });
});
"""


def _main():
    parser = argparse.ArgumentParser(description="Export Fair Share calculation results as an interactive HTML map.")
    parser.add_argument("result_json", type=Path, help="JSON saved from fair_share.calculate().")
    parser.add_argument("output_html", type=Path)
    parser.add_argument("--variant", choices=("base", "adjusted"), default="adjusted")
    parser.add_argument("--metric", choices=("relative", "absolute"), default="relative")
    args = parser.parse_args()
    result = json.loads(args.result_json.read_text(encoding="utf-8"))
    page = render_fair_share_map(result, variant=args.variant, metric=args.metric)
    args.output_html.write_text(page, encoding="utf-8")


